import React, { useContext, useState } from "react";
import "./CSS/Checkout.css";
import { ShopContext } from "../Context/ShopContext";
import { useNavigate } from "react-router-dom";

const Checkout = () => {
  const { getTotalCartAmount, all_product, cartItems, currency, clearCart } =
    useContext(ShopContext);
  const navigate = useNavigate();

  const [address, setAddress] = useState({
    firstName: "",
    lastName: "",
    email: "",
    phone: "",
    street: "",
    city: "",
    state: "",
    zipcode: "",
  });

  const [paymentMethod, setPaymentMethod] = useState("COD");
  const [upiId, setUpiId] = useState("");
  const [cardDetails, setCardDetails] = useState({ number: "", expiry: "", cvv: "" });
  const [bank, setBank] = useState("State Bank of India");

  const changeAddressHandler = (e) => {
    setAddress({ ...address, [e.target.name]: e.target.value });
  };

  const handlePlaceOrder = async (e) => {
    e.preventDefault();

    if (!address.firstName || !address.phone || !address.street || !address.city || !address.zipcode) {
      alert("Please fill in all required shipping address fields.");
      return;
    }

    // Build items list
    let orderItems = [];
    all_product.forEach((item) => {
      if (cartItems[item.id] > 0) {
        orderItems.push({
          productId: item.id,
          name: item.name,
          image: item.image,
          category: item.category,
          price: item.new_price,
          quantity: cartItems[item.id],
        });
      }
    });

    if (orderItems.length === 0) {
      alert("Your cart is empty!");
      return;
    }

    const orderData = {
      items: orderItems,
      amount: getTotalCartAmount(),
      address: address,
      paymentMethod: paymentMethod,
    };

    try {
      const token = localStorage.getItem("auth-token");
      const response = await fetch("http://localhost:4000/placeorder", {
        method: "POST",
        headers: {
          Accept: "application/json",
          "auth-token": token,
          "Content-Type": "application/json",
        },
        body: JSON.stringify(orderData),
      });

      const data = await response.json();

      if (data.success) {
        alert("🎉 Order Placed Successfully!");
        clearCart();
        navigate("/myorders");
      } else {
        alert(data.errors || "Failed to place order");
      }
    } catch (error) {
      console.error("Order Placement Error:", error);
      alert("Something went wrong while placing order.");
    }
  };

  return (
    <div className="checkout">
      <div className="checkout-container">
        {/* Left Side: Delivery Information & Payment Method */}
        <div className="checkout-left">
          <h2>Delivery Information</h2>
          <form className="checkout-form" onSubmit={handlePlaceOrder}>
            <div className="form-row">
              <input
                required
                type="text"
                name="firstName"
                placeholder="First Name *"
                value={address.firstName}
                onChange={changeAddressHandler}
              />
              <input
                required
                type="text"
                name="lastName"
                placeholder="Last Name *"
                value={address.lastName}
                onChange={changeAddressHandler}
              />
            </div>
            <div className="form-row">
              <input
                required
                type="email"
                name="email"
                placeholder="Email Address *"
                value={address.email}
                onChange={changeAddressHandler}
              />
              <input
                required
                type="text"
                name="phone"
                placeholder="Phone Number *"
                value={address.phone}
                onChange={changeAddressHandler}
              />
            </div>
            <input
              required
              type="text"
              name="street"
              placeholder="Street Address / House No. *"
              value={address.street}
              onChange={changeAddressHandler}
            />
            <div className="form-row">
              <input
                required
                type="text"
                name="city"
                placeholder="City *"
                value={address.city}
                onChange={changeAddressHandler}
              />
              <input
                required
                type="text"
                name="state"
                placeholder="State *"
                value={address.state}
                onChange={changeAddressHandler}
              />
              <input
                required
                type="text"
                name="zipcode"
                placeholder="PIN Code *"
                value={address.zipcode}
                onChange={changeAddressHandler}
              />
            </div>

            <h2 style={{ marginTop: "30px" }}>Select Payment Method</h2>
            <div className="payment-methods">
              <label
                className={`payment-option ${
                  paymentMethod === "COD" ? "active" : ""
                }`}
              >
                <input
                  type="radio"
                  name="payment"
                  value="COD"
                  checked={paymentMethod === "COD"}
                  onChange={() => setPaymentMethod("COD")}
                />
                💵 Cash on Delivery (COD)
              </label>

              <label
                className={`payment-option ${
                  paymentMethod === "UPI" ? "active" : ""
                }`}
              >
                <input
                  type="radio"
                  name="payment"
                  value="UPI"
                  checked={paymentMethod === "UPI"}
                  onChange={() => setPaymentMethod("UPI")}
                />
                📱 UPI (GPay / PhonePe / Paytm)
              </label>
              {paymentMethod === "UPI" && (
                <div className="payment-details-box">
                  <input
                    type="text"
                    placeholder="Enter UPI ID (e.g. user@okaxis)"
                    value={upiId}
                    onChange={(e) => setUpiId(e.target.value)}
                  />
                </div>
              )}

              <label
                className={`payment-option ${
                  paymentMethod === "Card" ? "active" : ""
                }`}
              >
                <input
                  type="radio"
                  name="payment"
                  value="Card"
                  checked={paymentMethod === "Card"}
                  onChange={() => setPaymentMethod("Card")}
                />
                💳 Credit / Debit Card
              </label>
              {paymentMethod === "Card" && (
                <div className="payment-details-box">
                  <input
                    type="text"
                    placeholder="Card Number (16 digits)"
                    value={cardDetails.number}
                    onChange={(e) =>
                      setCardDetails({ ...cardDetails, number: e.target.value })
                    }
                    style={{ marginBottom: "10px" }}
                  />
                  <div className="form-row">
                    <input
                      type="text"
                      placeholder="MM/YY"
                      value={cardDetails.expiry}
                      onChange={(e) =>
                        setCardDetails({ ...cardDetails, expiry: e.target.value })
                      }
                    />
                    <input
                      type="password"
                      placeholder="CVV"
                      value={cardDetails.cvv}
                      onChange={(e) =>
                        setCardDetails({ ...cardDetails, cvv: e.target.value })
                      }
                    />
                  </div>
                </div>
              )}

              <label
                className={`payment-option ${
                  paymentMethod === "NetBanking" ? "active" : ""
                }`}
              >
                <input
                  type="radio"
                  name="payment"
                  value="NetBanking"
                  checked={paymentMethod === "NetBanking"}
                  onChange={() => setPaymentMethod("NetBanking")}
                />
                🏦 Net Banking
              </label>
              {paymentMethod === "NetBanking" && (
                <div className="payment-details-box">
                  <select value={bank} onChange={(e) => setBank(e.target.value)}>
                    <option value="State Bank of India">State Bank of India</option>
                    <option value="HDFC Bank">HDFC Bank</option>
                    <option value="ICICI Bank">ICICI Bank</option>
                    <option value="Axis Bank">Axis Bank</option>
                    <option value="Kotak Mahindra Bank">Kotak Mahindra Bank</option>
                  </select>
                </div>
              )}
            </div>

            <button type="submit" className="place-order-btn">
              PLACE ORDER NOW ({currency}{getTotalCartAmount()})
            </button>
          </form>
        </div>

        {/* Right Side: Order Summary */}
        <div className="checkout-right">
          <h2>Order Summary</h2>
          <div className="checkout-summary">
            <div className="summary-item">
              <span>Items Subtotal:</span>
              <span>{currency}{getTotalCartAmount()}</span>
            </div>
            <div className="summary-item">
              <span>Shipping Charge:</span>
              <span style={{ color: "#2e7d32", fontWeight: 600 }}>FREE</span>
            </div>
            <div className="summary-item summary-total">
              <span>Total Amount:</span>
              <span>{currency}{getTotalCartAmount()}</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Checkout;
